function eng11AddSection(chapterId, section) {
  const chapter = ENG_11_DATA.find(item => item.id === chapterId);
  if (!chapter) throw new Error(`Unknown English chapter ${chapterId}`);
  const current = chapter.sections.find(item => item.source.pdfPage === section.source.pdfPage);
  if (current) Object.assign(current, section);
  else chapter.sections.push(section);
  return section;
}

function eng11Pair(original, urdu, pashto, extra = {}) {
  return { original, text: original, urdu, pashto, ...extra };
}

function eng11SourceText(value) {
  const escaped = typeof sanitize === 'function' ? sanitize(value) : String(value ?? '');
  return escaped.replaceAll('N_A', 'N<sub>A</sub>');
}

const eng11WordVocabulary = {};
function eng11RenderWordMeanings(text, sourceId) {
  const safe = value => typeof sanitize === 'function' ? sanitize(value) : String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const terms = Object.keys(eng11WordVocabulary).sort((a,b)=>b.length-a.length);
  if (!terms.length) return safe(String(text));
  const lookup = {}; for (const k of terms) lookup[k.toLowerCase()] = eng11WordVocabulary[k];
  const pattern = new RegExp('\\b(' + terms.map(term=>term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|') + ')\\b','gi');
  let result='', end=0, occurrence=0;
  for (const match of String(text).matchAll(pattern)) {
    result += safe(String(text).slice(end,match.index));
    const target = String(sourceId || 'eng11').replace(/[^a-zA-Z0-9_-]/g,'-') + '-word-' + (++occurrence);
    const meaning = lookup[match[0].toLowerCase()];
    result += `<button type="button" class="eng11-word-meaning" popovertarget="${target}" aria-label="${safe(match[0])}: اردو / پښتو" style="font:inherit;color:inherit;background:none;border:0;border-bottom:1px dotted currentColor;padding:0;cursor:pointer">${safe(match[0])}</button><span id="${target}" popover style="padding:.75em;max-width:22em"><strong>${safe(match[0])}</strong><br><span lang="ur" dir="rtl">${safe(meaning.ur)}</span><br><span lang="ps" dir="rtl">${safe(meaning.ps)}</span></span>`;
    end = match.index + match[0].length;
  }
  return result + safe(String(text).slice(end));
}

function eng11RenderPair(p) {
  const safe = value => typeof sanitize === 'function' ? sanitize(value) : String(value ?? '');
  let original = eng11RenderWordMeanings(p.original, p.id);
  let urdu = safe(p.urdu), pashto = safe(p.pashto);
  for (const math of p.inlineMath || []) {
    const formatted = math.denominator
      ? `<span role="math" aria-label="${safe(math.numerator)} divided by ${safe(math.denominator)}" style="display:inline-grid;vertical-align:middle;text-align:center;font-size:.85em;line-height:1.05"><span style="border-bottom:1px solid currentColor">${safe(math.numerator)}</span><span>${safe(math.denominator)}</span></span>`
      : `${safe(math.base)}<sub>${safe(math.subscript)}</sub>`;
    original = original.split(safe(math.token)).join(formatted);
    urdu = urdu.split(safe(math.token)).join(formatted);
    pashto = pashto.split(safe(math.token)).join(formatted);
  }
  if (p.listType === 'poem') { const br = s => s.split(String.fromCharCode(10)).join('<br>'); original = br(original); urdu = br(urdu); pashto = br(pashto); }
  const id = typeof sanitize === 'function' ? sanitize(p.id || '') : (p.id || '');
  const gap = p.sourceGap ? `<p class="eng11-source-note"><strong>Unresolved source:</strong> ${typeof sanitize === 'function' ? sanitize(p.sourceGap.note) : p.sourceGap.note}</p>` : '';
  const tag = p.kind === 'heading' ? 'h4' : 'p';
  const wrapper = p.kind === 'aside' ? 'aside' : 'article';
  return `<${wrapper} data-source-id="${id}"><${tag} lang="en">${original}</${tag}><details><summary>English / اردو / پښتو</summary><p lang="ur" dir="rtl">${urdu}</p><p lang="ps" dir="rtl">${pashto}</p></details>${(p.mathBlocks || []).map(eng11RenderEquation).join('')}${gap}</${wrapper}>`;
}

function eng11RenderFigure(f) {
  const safe = eng11SourceText;
  const translations = f.captionUrdu || f.captionPashto || f.labels
    ? `<details><summary>English / اردو / پښتو</summary>${f.captionUrdu ? `<p lang="ur" dir="rtl">${safe(f.captionUrdu)}</p>` : ''}${f.captionPashto ? `<p lang="ps" dir="rtl">${safe(f.captionPashto)}</p>` : ''}${(f.labels || []).map(label => `<p><span lang="en">${safe(label.en)}</span> · <span lang="ur" dir="rtl">${safe(label.ur)}</span> · <span lang="ps" dir="rtl">${safe(label.ps)}</span></p>`).join('')}</details>` : '';
  return `<figure>${f.svg}<figcaption>${safe(f.caption || '')}${translations}${f.sourceGap ? `<p class="eng11-source-note">Unresolved source: ${safe(f.sourceGap.note)}</p>` : ''}</figcaption></figure>`;
}

function eng11RenderSectionBody(sec) {
  if (!sec.flow) return eng11RenderParagraphs(sec.paras) + (sec.table ? eng11RenderTable(sec.table) : '') + (sec.equations || []).map(eng11RenderEquation).join('') + (sec.figures || []).map(eng11RenderFigure).join('');
  return sec.flow.map(block => {
    if (block.type === 'paragraphs') return eng11RenderParagraphs(block.ids.map(id => sec.paras.find(p => p.id === id)));
    if (block.type === 'figure') return eng11RenderFigure(sec.figures[block.index]);
    if (block.type === 'equation') return eng11RenderEquation(sec.equations[block.index]);
    if (block.type === 'table') return eng11RenderTable(block.index !== undefined ? sec.tables[block.index] : sec.table);
    throw new Error(`Unknown English source block: ${block.type}`);
  }).join('');
}

function eng11RenderParagraphs(paras) {
  let html='',group=null,tag='ul';
  for(const p of paras||[]) {
    const next=p.listGroup||null;
    if(group&&group!==next) html+=`</${tag}>`;
    if(next&&group!==next) {tag=p.listType==='ordered'?'ol':'ul';html+=tag==='ol'?'<ol style="list-style:none">':'<ul>';}
    html+=next?`<li>${eng11RenderPair(p)}</li>`:eng11RenderPair(p);
    group=next;
  }
  return html+(group?`</${tag}>`:'');
}

function renderEnglish11Tab(ch, tabId) {
  let sections=[...(ch.sections||[])].sort((a,b)=>a.source.pdfPage-b.source.pdfPage);
  if(tabId==='slos') sections=sections.filter(sec=>sec.layout==='outcomes');
  else if(['glossary','vocabulary','language','grammar','writing'].includes(tabId)) sections=sections.map(sec=>{
    const ids=new Set((sec.paras||[]).filter(p=>p.tab===tabId||(!p.tab&&sec.layout===tabId)).map(p=>p.id));
    const flow=(sec.flow||[]).map(block=>block.type==='paragraphs'?{...block,ids:block.ids.filter(id=>ids.has(id))}:(block.type==='table'&&sec.tables?.[block.index]&&(sec.tables[block.index].tab===tabId||(!sec.tables[block.index].tab&&sec.layout===tabId)))?block:null).filter(block=>block&&(block.type!=='paragraphs'||block.ids.length));
    return {...sec,flow,table:undefined,equations:[],figures:[],paras:(sec.paras||[]).filter(p=>ids.has(p.id))};
  }).filter(sec=>sec.flow.length);
  else if(tabId==='concepts') sections=sections.filter(sec=>sec.layout!=='outcomes');
  else if(tabId==='exercise') sections=sections.map(sec=>{
    const paras=(sec.paras||[]).filter(p=>p.exampleId||p.exerciseId||p.role==='question'||p.role==='solution');
    const ids=new Set(paras.map(p=>p.id));
    const isExerciseBlock=block=>{
      const item=block.type==='equation'?sec.equations?.[block.index]:block.type==='figure'?sec.figures?.[block.index]:null;
      return item&&(item.exampleId||item.exerciseId);
    };
    const flow=sec.flow?sec.flow.map(block=>block.type==='paragraphs'?{...block,ids:block.ids.filter(id=>ids.has(id))}:isExerciseBlock(block)?block:null).filter(block=>block&&(block.type!=='paragraphs'||block.ids.length)):undefined;
    return {...sec,flow,table:undefined,equations:flow?sec.equations:(sec.equations||[]).filter(eq=>eq.exampleId||eq.exerciseId),figures:flow?sec.figures:(sec.figures||[]).filter(f=>f.exampleId||f.exerciseId),paras};
  }).filter(sec=>sec.paras.length);
  else if(tabId==='formulas') sections=sections.map(sec=>({...sec,flow:undefined,table:undefined,figures:(sec.figures||[]).filter(f=>f.role==='equation'),paras:[],equations:[...(sec.equations||[]),...(sec.paras||[]).flatMap(p=>p.mathBlocks||[])]})).filter(sec=>sec.equations.length||sec.figures.length);
  else if(tabId!=='lesson') sections=[];
  if(!sections.length) return `<p class="eng11-source-note">${ch.sourceGap ? '<strong>Source gap:</strong> ' + eng11SourceText(ch.sourceGap) : 'Source comparison is in progress for this section.'}</p>`;
  const draft=sections.some(sec=>!String(sec.auditStatus||'').startsWith('verified'));
  return (draft?'<p class="eng11-source-note">This view includes draft or unresolved source records. Page-specific notes identify known gaps.</p>':'')+sections.map(sec=>`<section data-source-page="${sec.source.pdfPage}"><h3>${eng11SourceText(sec.headingUrdu)} / ${eng11SourceText(sec.title)} / ${eng11SourceText(sec.headingPashto)}</h3><p>Scan ${sec.source.pdfPage}${sec.source.printedPage?` · Printed page ${sec.source.printedPage}`:''}${String(sec.auditStatus||'').startsWith('verified')?' · Source checked':''}</p>${sec.sourceNote?`<p class="eng11-source-note"><strong>Source review note:</strong> ${eng11SourceText(sec.sourceNote)}</p>`:''}${eng11RenderSectionBody(sec)}</section>`).join('');
}

function eng11RenderEquation(eq) {
  const safe = value => typeof sanitize === 'function' ? sanitize(value) : String(value ?? '');
  const fraction = parts => `<span>${eng11SourceText(parts.left)} = </span><span style="display:inline-grid;vertical-align:middle;text-align:center;line-height:1.5"><span style="border-bottom:1px solid currentColor;padding:0 .25em">${eng11SourceText(parts.numerator)}</span><span style="padding:0 .25em">${eng11SourceText(parts.denominator)}</span></span>${parts.result ? ` = ${eng11SourceText(parts.result)}` : ''}${parts.after ? ` ${eng11SourceText(parts.after)}` : ''}`;
  const sourceLine = line => {
    let formatted = eng11SourceText(line);
    if (eq.formatSourceNotation) {
      formatted = formatted.replace(/([13])\/([12])/g, (_, n, d) => `<span style="display:inline-grid;vertical-align:middle;text-align:center"><span style="border-bottom:1px solid currentColor">${n}</span><span>${d}</span></span>`)
        .replace(/\((s|g|aq|l)\)/g, '<sub>($1)</sub>');
    }
    if (eq.cancelZeros) formatted = formatted.replace(/(?<!\d)(100|10)(?!\d)/g, value => value.slice(0,-1)+'<del>0</del>');
    if (eq.cancelUnits && String(line).includes('×')) formatted = formatted.replace(/mol(?![a-z])/g, '<del>mol</del>');
    return formatted;
  };
  const nativeLines = lines => lines.map(row => `<div>${row.map(part => part.text !== undefined ? sourceLine(part.text) : `<span style="display:inline-grid;vertical-align:middle;text-align:center;line-height:1.5"><span style="border-bottom:1px solid currentColor;padding:0 .25em">${sourceLine(part.numerator)}</span><span style="padding:0 .25em">${sourceLine(part.denominator)}</span></span>`).join('')}</div>`).join('');
  const content = typeof SpaceBookLessonMath !== 'undefined' && typeof katex !== 'undefined'
    ? SpaceBookLessonMath.renderMath({latex:eq.latex,display:true})
    : eq.nativeTable ? `<table><tbody>${eq.nativeTable.rows.map(row=>`<tr>${row.map(cell=>`<td style="padding:.15em .7em;text-align:center">${sourceLine(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table>`
    : eq.nativeLines ? nativeLines(eq.nativeLines.en)
    : eq.parts ? `${fraction(eq.parts)}${eq.number ? ` <span>(${safe(eq.number)})</span>` : ''}`
    : eq.lines ? eq.lines.map(line=>`<div>${sourceLine(line)}</div>`).join('')
    : safe(eq.fallback || eq.latex);
  const translations = eq.nativeLines ? `<details><summary>English / اردو / پښتو</summary><div lang="ur" dir="rtl">${nativeLines(eq.nativeLines.ur)}</div><div lang="ps" dir="rtl">${nativeLines(eq.nativeLines.ps)}</div></details>` : eq.translations ? `<details><summary>English / اردو / پښتو</summary><div lang="ur" dir="rtl">${fraction(eq.translations.ur)}</div><div lang="ps" dir="rtl">${fraction(eq.translations.ps)}</div></details>` : eq.lineTranslations ? `<details><summary>English / اردو / پښتو</summary><div lang="ur" dir="rtl">${eq.lineTranslations.ur.map(line=>`<div>${sourceLine(line)}</div>`).join('')}</div><div lang="ps" dir="rtl">${eq.lineTranslations.ps.map(line=>`<div>${sourceLine(line)}</div>`).join('')}</div></details>` : '';
  return `<div role="math" aria-label="${safe(eq.accessible || eq.fallback)}" data-source-id="${safe(eq.id || '')}">${content}${translations}</div>`;
}

function eng11RenderTable(table) {
  const safe = value => typeof sanitize === 'function' ? sanitize(value) : String(value ?? '');
  return `<div class="eng11-table-wrap"><table><caption>${safe(table.caption)}${table.captionUrdu || table.captionPashto ? `<details><summary>English / اردو / پښتو</summary><span lang="ur" dir="rtl">${safe(table.captionUrdu)}</span><br><span lang="ps" dir="rtl">${safe(table.captionPashto)}</span></details>` : ''}</caption><thead><tr>${table.headers.map(h => `<th scope="col">${safe(h.en)}<details><summary>ترجمہ</summary><span lang="ur" dir="rtl">${safe(h.ur)}</span><br><span lang="ps" dir="rtl">${safe(h.ps)}</span></details></th>`).join('')}</tr></thead><tbody>${table.rows.map(row => `<tr>${row.map((cell, i) => `<td>${cell.svg || ''}${safe(cell.en).replace(/\n/g, '<br>')}${cell.sourceGap ? `<p class="eng11-source-note">Unresolved source: ${safe(cell.sourceGap.note)}</p>` : ''}${cell.ur || cell.ps ? `<details><summary>ترجمہ</summary><span lang="ur" dir="rtl">${safe(cell.ur)}</span><br><span lang="ps" dir="rtl">${safe(cell.ps)}</span></details>` : ''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function eng11TableCell(en, ur = '', ps = '') { return { en: String(en), ur: String(ur), ps: String(ps) }; }

function english11SourceSearchText(ch) {
  return [ch.title, ch.titleUrdu, ch.titlePashto, ...(ch.sections || []).flatMap(sec => [
    sec.title, sec.headingUrdu, sec.headingPashto,
    ...(sec.paras || []).flatMap(p => [p.original, p.urdu, p.pashto]),
    ...(sec.figures || []).flatMap(f => [f.caption, f.captionUrdu, f.captionPashto]),
    ...(sec.tables || []).flatMap(t => [t.caption, ...(t.rows || []).flat().map(c => typeof c === 'string' ? c : c.en)])
  ])].filter(Boolean).join(' ');
}

function english11SourceSearchText(ch) {
  return [ch.title, ch.titleUrdu, ch.titlePashto, ...(ch.sections || []).flatMap(sec => [
    sec.title, sec.headingUrdu, sec.headingPashto,
    ...(sec.paras || []).flatMap(p => [p.original, p.urdu, p.pashto]),
    ...(sec.figures || []).flatMap(f => [f.caption, f.captionUrdu, f.captionPashto]),
    ...(sec.tables || []).flatMap(t => [t.caption, ...(t.rows || []).flat().map(c => typeof c === 'string' ? c : c.en)])
  ])].filter(Boolean).join(' ');
}

